solution:
// Convert between hexadecimal and standard Base64 text, in either
// direction, validating the input.
// If value starts with "hex:", the rest must be an even number (possibly zero)
// of hex digits 0-9, a-f, A-F, read in pairs as bytes; return "b64:" followed
// by the standard Base64 encoding of those bytes: alphabet A-Z a-z 0-9 + /
// (values 0 to 63 in that order), each 3 bytes become 4 characters, and a final
// group of 1 or 2 bytes is padded with "==" or "=" to 4 characters.
// If value starts with "b64:", the rest must be canonical Base64: a length that
// is a multiple of 4 (possibly zero), only alphabet characters, except that the
// last group may end in "=" or "==" (padding nowhere else, never 3 or 4 "="),
// and the bits that the padding discards must be zero (so "QQ==" is valid but
// "QR==" is not). Return "hex:" followed by the decoded bytes as lowercase hex,
// two digits per byte.
// For every other input (another or uppercase prefix, an odd number of hex
// digits, a bad character, whitespace, wrong length, misplaced padding,
// non-zero discarded bits) return the string "invalid".
// Examples:
//   base64_convert("hex:4d616e") == "b64:TWFu"
//   base64_convert("b64:TWE=") == "hex:4d61"
fn base64_convert(value: Str) -> Str {
  let rest = chars(substr(value, 4, str_len(value)));
  if starts_with(value, "hex:") {
    match hex_bytes(rest) {
      Some(data) => "b64:" ++ b64_encode(data),
      None => "invalid",
    }
  } else if starts_with(value, "b64:") {
    match b64_decode(rest) {
      Some(data) => "hex:" ++ join(map(data, hex2), ""),
      None => "invalid",
    }
  } else {
    "invalid"
  }
}

fn b64_alphabet() -> List[Str] {
  chars("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/")
}

fn hex_digit(c: Str) -> Int {
  unwrap_or(index_of(chars("0123456789abcdef"), to_lower(c)), -1)
}

fn hex2(b: Int) -> Str {
  let ds = chars("0123456789abcdef");
  ds[b / 16] ++ ds[b % 16]
}

fn hex_bytes(cs: List[Str]) -> Option[List[Int]] {
  if len(cs) % 2 != 0 {
    return None;
  }
  let mut out: List[Int] = [];
  let mut i = 0;
  while i < len(cs) {
    let hi = hex_digit(cs[i]);
    let lo = hex_digit(cs[i + 1]);
    if hi < 0 || lo < 0 {
      return None;
    }
    out = push(out, hi * 16 + lo);
    i = i + 2;
  }
  Some(out)
}

fn b64_encode(data: List[Int]) -> Str {
  let abc = b64_alphabet();
  let mut out = "";
  let mut i = 0;
  while i < len(data) {
    let n = min(3, len(data) - i);
    let b1 = if n > 1 { data[i + 1] } else { 0 };
    let b2 = if n > 2 { data[i + 2] } else { 0 };
    let v = data[i] * 65536 + b1 * 256 + b2;
    out = out ++ abc[v / 262144] ++ abc[v / 4096 % 64];
    out = out ++ (if n > 1 { abc[v / 64 % 64] } else { "=" });
    out = out ++ (if n > 2 { abc[v % 64] } else { "=" });
    i = i + 3;
  }
  out
}

fn b64_decode(cs: List[Str]) -> Option[List[Int]] {
  let abc = b64_alphabet();
  if len(cs) % 4 != 0 {
    return None;
  }
  let mut out: List[Int] = [];
  let mut i = 0;
  while i < len(cs) {
    let mut pad = 0;
    if i + 4 == len(cs) && cs[i + 3] == "=" {
      pad = if cs[i + 2] == "=" { 2 } else { 1 };
    }
    let mut v = 0;
    for k in range(0, 4 - pad) {
      // also rejects "=" anywhere but the final padding
      match index_of(abc, cs[i + k]) {
        Some(d) => { v = v * 64 + d; },
        None => { return None; },
      }
    }
    v = v * pow(64, pad);
    // bits dropped by the padding must be zero
    if (pad == 1 && v % 256 != 0) || (pad == 2 && v % 65536 != 0) {
      return None;
    }
    out = concat(out, take([v / 65536, v / 256 % 256, v % 256], 3 - pad));
    i = i + 4;
  }
  Some(out)
}
